components.css:
/* ── projects ───────────────────────────────────────────── */
/* 벤토: 한 그리드 안에서 크기로 중요도를 말한다. 열 수·높이·이미지 폭은 PROJECTS[]가
   --span/--minh/--imgw 커스텀 속성으로 넘기고, 모바일 블록은 그 소비처만 덮어쓴다. */
[data-projgrid]{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.ds-proj-card{grid-column:span var(--span,2);min-height:var(--minh,200px);display:grid;grid-template-columns:minmax(0,1fr) min(30%,var(--imgw,190px));border-radius:14px;overflow:hidden;background:var(--bg);border:1px solid var(--line);color:var(--fg);cursor:pointer;transition:background .15s}
.ds-proj-card:hover,.ds-proj-card:focus-within{background:var(--card)}
/* 카드 전체가 클릭 면이지만 접근성 트리에서는 제목 안의 버튼 하나만 컨트롤이다.
   article 자체에 role=button을 주면 h3가 버튼 이름 속으로 사라져 헤딩 탐색에서 빠진다. */
.ds-proj-card:has(.ds-pc-btn:focus-visible){outline:2px solid var(--ink);outline-offset:3px}
.ds-pc-btn{all:unset;display:inline;cursor:pointer;color:inherit;font:inherit;letter-spacing:inherit}
.ds-pc-btn:focus-visible{outline:none}
.ds-pc-text{min-width:0;padding:24px 24px 22px;display:flex;flex-direction:column;gap:12px}
.ds-proj-card[data-span="4"] .ds-pc-text{padding:24px 26px}
.ds-pc-eyebrow{font-size:14px;letter-spacing:.1em;color:var(--muted)}
.ds-pc-title{margin:0;font-size:22px;line-height:1.25;letter-spacing:-.028em;font-weight:600;color:var(--fg)}
.ds-pc-blurb{margin:0;font-size:16px;line-height:1.6;color:var(--sub)}
/* 이미지가 없어도 자리는 유지하되 본문보다 시선을 끌지 않는다. */
.ds-pc-img{min-width:0;display:flex;align-items:center;justify-content:center;background:var(--card);border-left:1px solid var(--line-soft)}
.ds-pc-img img{width:100%;height:100%;object-fit:cover;display:block}
.ds-pc-cap{font-size:11px;letter-spacing:.04em;color:var(--muted);padding:8px;text-align:center}
